const upstream = join(dir, 'upstream.git');
const repo = join(dir, 'work');

await $`git init --quiet --bare --template= --initial-branch=main ${upstream}`.env(env).quiet();
await $`git clone --quiet --template= ${upstream} ${repo}`.env(env).quiet();
await $`git config user.name harbor`.env(env).cwd(repo).quiet();
await $`git config user.email harbor@example.com`.env(env).cwd(repo).quiet();
await $`git config commit.gpgsign false`.env(env).cwd(repo).quiet();
await $`git config tag.gpgsign false`.env(env).cwd(repo).quiet();

writeFileSync(join(repo, 'README.md'), 'hello\n');

await $`git add README.md`.env(env).cwd(repo).quiet();
await $`git commit --quiet -m initial`.env(env).cwd(repo).quiet();
await $`git push --quiet origin main`.env(env).cwd(repo).quiet();
await $`git remote set-head origin main`.env(env).cwd(repo).quiet();

return { repo, env };

